package cl.sonidovivo;

import io.swagger.v3.oas.models.*; import io.swagger.v3.oas.models.security.*; import jakarta.validation.ConstraintViolationException; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;

@Configuration class OpenApiConfig { @Bean OpenAPI sonidoVivoOpenAPI(){return new OpenAPI().info(new io.swagger.v3.oas.models.info.Info().title("Sonido Vivo API").version("1.0.0")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));}}
@Configuration class SeedData { @Bean CommandLineRunner seed(UsuarioRepository usuarios,PasswordEncoder encoder){return args->{if(usuarios.findByEmailIgnoreCase("admin@sonidovivo.cl").isEmpty())usuarios.save(new Usuario("Administración Sonido Vivo","admin@sonidovivo.cl",encoder.encode("admin123"),Rol.ADMIN));if(usuarios.findByEmailIgnoreCase("vendedor@sonidovivo.cl").isEmpty())usuarios.save(new Usuario("Vendedor Sonido Vivo","vendedor@sonidovivo.cl",encoder.encode("vendedor123"),Rol.VENDEDOR));};}}
record ApiError(Instant timestamp,int status,String message,Map<String,String> errors){}
@RestControllerAdvice class GlobalExceptionHandler {@ExceptionHandler(NotFoundException.class)ResponseEntity<ApiError> notFound(NotFoundException e){return error(HttpStatus.NOT_FOUND,e.getMessage(),Map.of());}@ExceptionHandler({BadRequestException.class,DataIntegrityViolationException.class,ConstraintViolationException.class})ResponseEntity<ApiError> bad(RuntimeException e){return error(HttpStatus.BAD_REQUEST,e.getMessage(),Map.of());}@ExceptionHandler(UnauthorizedException.class)ResponseEntity<ApiError> unauthorized(UnauthorizedException e){return error(HttpStatus.UNAUTHORIZED,e.getMessage(),Map.of());}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){Map<String,String> errors=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));return error(HttpStatus.BAD_REQUEST,"Validación fallida",errors);}@ExceptionHandler(Exception.class)ResponseEntity<ApiError> generic(Exception e){return error(HttpStatus.INTERNAL_SERVER_ERROR,"Error interno del servidor",Map.of());}private ResponseEntity<ApiError> error(HttpStatus status,String m,Map<String,String> errors){return ResponseEntity.status(status).body(new ApiError(Instant.now(),status.value(),m,errors));}}